"""Course home, practice hub, glossary, assessment and sources."""
from html import escape


def section(id, title, body):
    return f'<section class="lesson-section" id="{id}"><h2>{title}</h2>{body}</section>'


def page(id, title, description, sections, objectives=(), recap=(), minutes=5):
    return dict(id=id, title=title, description=description, minutes=minutes,
                objectives=list(objectives), sections=sections, recap=list(recap))


LABS = [
    ("explorer", "A file has three coordinates", "Create a file, switch the container, and list a prefix. Explain why the same key in another container is a different blob.", "foundations"),
    ("sas", "Give access for a limited time", "Try a read using a write-only grant, then advance the simulated clock beyond expiry. Predict which requests fail before you try them.", "access"),
    ("routing", "Where does this key go?", "Compare a customer-rooted key, a deployment key and a bare key. Then introduce a conflicting root and explain the fallback.", "keys"),
    ("paths", "Keep the saved path or rebuild it?", "Change case 214 to 9001. Compare reading a saved upload with rebuilding a bundle. Try a validator based on the new ID.", "paths"),
    ("journey", "Follow complaint.pdf", "Walk through the upload and AI extraction. At each step identify who chooses the key, who transfers the bytes, and what the database remembers.", "file-journey"),
    ("migration", "Move the rows and the files", "Copy database rows without blobs, then add the blobs and matching routing configuration. Compare saved artifacts with rebuilt bundles and bare keys.", "migration"),
    ("debugging", "Find the cause, then fix it", "Inspect the evidence in each incident. Distinguish routing, missing bytes, expired access and an application validator before choosing a fix.", "debugging"),
]


def supplements(lessons, glossary, sources, questions):
    cards = ''.join(f'<a class="card" href="{m["id"]}.html"><span class="tag">{i:02d} / {len(lessons):02d} · {m["minutes"]} min</span><b>{escape(m["title"])}</b><small>{escape(m["description"])}</small></a>' for i, m in enumerate(lessons, 1))
    index = page("index", "Understand every file.\nFollow every step.",
        "Learn Azure Blob Storage from zero, then follow a real CrimeOS file from upload to AI, migration and debugging.", [
        section("start", "Learn a little. See it happen. Try it yourself.", '''<p>You do not need an Azure account to start. Begin with a storage account, a container and one file. Each lesson adds one idea, a worked example, a visual explanation and a prediction to check.</p>
        <div class="actions"><a class="btn btn-primary" id="resume-course" href="foundations.html">Start lesson 01 →</a><a class="btn" href="practice.html">Open the storage labs</a></div>
        <div class="stat-grid"><div class="stat"><strong>11</strong><span>guided lessons</span></div><div class="stat"><strong>7</strong><span>interactive browser labs</span></div><div class="stat"><strong>QUESTION_COUNT</strong><span>explained scenario questions</span></div><div class="stat"><strong>12 / 12</strong><span>parts of your guide covered</span></div></div>'''.replace('QUESTION_COUNT', str(len(questions)))),
        section("mental-model", "One file, three coordinates", '''<div class="flow" aria-label="A blob is identified by account, container and key"><div><b>Storage account</b><small>The building: a distinct place in Azure</small></div><span aria-hidden="true">→</span><div><b>Container</b><small>The cupboard inside that building</small></div><span aria-hidden="true">→</span><div><b>Blob key</b><small>The full name of one stored object</small></div></div><p>CrimeOS adds a routing decision: it examines the start of the blob key to select a storage connection. The customer who owns a case influences how that key is built. That is why learning the key is as important as learning the URL.</p><div class="callout"><b class="callout-title">Two kinds of knowledge</b><p><strong>Azure concepts</strong> explain the storage service. <strong>CrimeOS examples</strong> explain the application behavior described in your November 6, 2026 guide. The routing rule and URL parser belong to CrimeOS.</p></div>'''),
        section("route", "Choose a route through the course", '''<div class="table-wrap"><table><thead><tr><th>Your goal</th><th>Start here</th></tr></thead><tbody><tr><td>I am completely new</td><td><a href="foundations.html">Lesson 01: storage basics</a>, then follow Next at the bottom of each page.</td></tr><tr><td>I work on the backend</td><td><a href="ownership.html">Ownership</a> → <a href="keys.html">key routing</a> → <a href="rules.html">implementation rules</a>.</td></tr><tr><td>A file is missing</td><td><a href="debugging.html">The debugging lesson</a> and its incident simulator.</td></tr><tr><td>I am moving case data</td><td><a href="paths.html">Saved versus built paths</a> → <a href="migration.html">migration</a>.</td></tr><tr><td>I want to check what I remember</td><td><a href="quiz.html">Scenario quiz</a> and the <a href="glossary.html">searchable glossary</a>.</td></tr></tbody></table></div><p>Allow roughly four to six hours with practice, or work through one lesson at a time. Progress is saved in this browser when browser storage is available.</p>'''),
        section("curriculum", "Your learning path", '<div class="cards">' + cards + '</div>'),
        section("how", "Use a prediction before every click", '''<ol class="checklist"><li><strong>Read:</strong> learn the term in plain language.</li><li><strong>See:</strong> follow the diagram and one concrete file.</li><li><strong>Predict:</strong> say which account, key or permission should be used.</li><li><strong>Try:</strong> change one input in the lab and inspect the result.</li><li><strong>Explain:</strong> answer the lesson check and read the reason.</li><li><strong>Recall:</strong> revisit the quiz after a break.</li></ol><p>The labs use fictional examples and an in-memory model. They do not connect to Azure, upload your files, inspect your database or generate real credentials. Lesson text and answer explanations remain readable without JavaScript.</p>''')
    ], minutes=5)

    practice_sections = [section("lab-intro", "Make one change, then explain the result", '''<p>These seven labs collect the interactive parts of the course. Use them in order, or return to the concept you need. Each lab runs in your browser. Its reset button resets the experiment; your completed-lab record is managed separately.</p><p class="lab-progress" id="lab-progress" role="status">Seven experiments · no Azure account required</p><noscript><p>Enable JavaScript for the simulations. The linked lessons contain the worked examples, diagrams and hidden answers.</p></noscript>''')]
    for i, (id, title, goal, topic) in enumerate(LABS, 1):
        practice_sections.append(section('lab-' + id, f'{i:02d}. {title}',
            f'<p>{escape(goal)}</p><p><a href="{topic}.html">Review the lesson →</a> <span class="chip" data-lab-badge="{id}">Ready to explore</span></p><div data-lab="{id}"></div>'))
    practice_sections.append(section("transfer", "Explain a new feature before coding it", '''<p>A case needs a generated PDF that must still open after a database migration. Write down the owner, the key helper, the saved column, the reader and the migration plan before opening the answer.</p><details class="reveal"><summary>Compare your design with a worked answer</summary><div><p>Resolve the case's owning customer. Build a key under <code>MEDIAFILES_LOCATION</code>, pass it through <code>key_for_case</code>, write using the routed storage adapter, and save the returned key or URL. Read the saved value later. A migration must preserve that key, copy the bytes separately, and configure the same account root in the destination. Avoid checking the saved path against a path rebuilt with the new case ID. Test both a customer with its own storage and one that uses deployment storage.</p></div></details>'''))
    practice = page("practice", "The storage lab", "Seven experiments that make ownership, routing, access and migration visible.", practice_sections,
        ["Predict a storage decision before running it.", "Explain a failure using the visible evidence.", "Apply the same reasoning to a new file feature."],
        ["A lab is a model of the guide, not a live cloud connection.", "Change one variable at a time and trace its effect."], 35)

    entries = ''.join(f'<article class="glossary-entry" data-glossary><h3>{escape(g["term"])}</h3><p>{escape(g["meaning"])}</p><p class="muted"><strong>Example:</strong> <code>{escape(g["example"])}</code></p></article>' for g in glossary)
    glossary_page = page("glossary", "Words you can explain", "A searchable glossary with plain meanings and concrete examples.", [
        section("words", "Start with the word that is unclear", f'<div class="filter-bar only-js"><label class="field" for="glossary-search">Find a word or example<input type="search" id="glossary-search" placeholder="Try: key, account, saved path…"></label><span id="glossary-count" role="status">{len(glossary)} terms</span></div><div class="glossary-grid">{entries}</div><p id="glossary-empty" class="empty" hidden>No matching terms. Try another word.</p>'),
        section("distinctions", "Three distinctions to keep clear", '''<div class="flow"><div><b>Customer account ≠ storage account</b><small>A CrimeOS customer can have its own Azure storage, or use deployment storage.</small></div><div><b>Blob key ≠ account access key</b><small>The blob key is a name. The account access key is a secret.</small></div><div><b>Saved path ≠ bytes</b><small>A database value describes where to look. It does not contain the stored PDF.</small></div></div>''')
    ], minutes=8)

    question_bank = ''.join(f'<details class="reveal" data-question-topic="{q["topic"]}"><summary>{i}. {escape(q["prompt"])}</summary><div><p><strong>{escape(q["options"][q["correct"]]["text"])}</strong></p><p>{escape(q["options"][q["correct"]]["why"])}</p><p><a href="{q["topic"]}.html">Review this lesson</a></p></div></details>' for i, q in enumerate(questions, 1))
    topics = ''.join(f'<option value="{m["id"]}">{escape(m["title"])}</option>' for m in lessons)
    quiz = page("quiz", "Can you predict what happens?", "Check your understanding with realistic cases and a reason for every answer.", [
        section("assessment", "Try the scenario quiz", f'''<p>Choose an answer before checking it. Your latest answer is saved in this browser. Use Try again to revisit an answer, or filter to the questions you missed.</p><div id="quiz-app" class="only-js"><div class="quiz-controls"><label class="field" for="quiz-topic">Topic<select id="quiz-topic"><option value="all">All lessons</option>{topics}</select></label><label class="field" for="quiz-mode">Question set<select id="quiz-mode"><option value="all">All questions</option><option value="missed">Missed questions</option><option value="unanswered">Unanswered questions</option></select></label></div><p id="quiz-score" class="quiz-summary" role="status"></p><p id="quiz-position" class="question-progress"></p><div id="quiz-card"></div><div class="actions"><button class="btn" id="quiz-prev" type="button">← Previous question</button><button class="btn btn-primary" id="quiz-next" type="button">Next question →</button></div></div><noscript><p>Use the full question bank below. Answers open individually.</p></noscript>'''),
        section("question-bank", f"All {len(questions)} questions, with answers", '<p>Use this readable bank for revision, printing, or learning without JavaScript.</p>' + question_bank)
    ], ["Explain the route and identity of a file.", "Distinguish a missing blob from denied access.", "Reason about a changed ID without guessing."],
        ["The explanation matters more than the score.", "Return to the matching lesson whenever a decision surprises you."], 25)

    official = ''.join(f'<li><a href="{escape(s["url"], quote=True)}">{escape(s["title"])}</a><p>{escape(s["description"])}</p></li>' for s in sources if s.get('url', '').startswith('https://'))
    reference = page("reference", "Keep the useful parts close", "A practical reference, source notes and controls for your learning progress.", [
        section("quick-reference", "The decisions to make for every file", '''<div class="table-wrap"><table><thead><tr><th>Question</th><th>Decision</th><th>Read more</th></tr></thead><tbody><tr><td>Who owns this file?</td><td>Case, user, chat, customer, or explicitly deployment-wide</td><td><a href="ownership.html">Ownership</a></td></tr><tr><td>How is its key built?</td><td>Deployment media root → correct owner helper → routed key</td><td><a href="keys.html">Keys and helpers</a></td></tr><tr><td>How is it found later?</td><td>Saved value, or a deterministic key for a regenerable file</td><td><a href="paths.html">Saved and built paths</a></td></tr><tr><td>Who gets access?</td><td>Backend uses its credentials; browser and AI receive limited grants</td><td><a href="backend-ai.html">Backend and AI</a></td></tr><tr><td>What must a move preserve?</td><td>Rows, bytes, route, container, ownership and reader compatibility</td><td><a href="migration.html">Migration</a></td></tr><tr><td>Is the copy safe?</td><td>Copy strictly → verify completion → delete only after success</td><td><a href="rules.html">Implementation rules</a></td></tr></tbody></table></div>'''),
        section("guide", "Where the CrimeOS examples come from", '''<p>The supplied <code>azure-storage-learning-guide.html</code>, dated <strong>2026-11-06</strong>, is the source for the CrimeOS-specific lessons. Its stated basis is the demo account-storage branch and the audits described in that guide. This course preserves that snapshot; it is not a new audit of every active CrimeOS branch.</p><p>The original guide's glossary becomes the <a href="glossary.html">glossary</a>; Parts 1–11 become the eleven lessons; Part 12 becomes the <a href="quiz.html">assessment</a>. The seven labs let you experiment with those same rules. Real storage names appearing in lesson examples are quoted from the guide. Lab names and credentials are fictional.</p><p>Examples of current-code checks before changing a service: confirm the routing helper and its cache behavior, the model's actual table name, the storage-grants allowlist, and the migration tool's active branch. The <a href="code-map.html">code map</a> tells you where the guide found these behaviors.</p>'''),
        section("sources", "Azure documentation", '<p>These primary sources explain the general Azure concepts. CrimeOS-specific behavior is attributed to the supplied guide instead.</p><ul class="reference-list">' + official + '</ul>'),
        section("beyond", "After this course: operating the storage account", '''<p>This learning path covers Blob Storage and the complete supplied CrimeOS guide. Azure also has storage services and operating choices beyond that guide. Continue with these topics when you need them:</p><ul class="reference-list"><li><a href="https://learn.microsoft.com/en-us/azure/storage/blobs/access-tiers-overview">Access tiers</a>: compare frequent reads with cooler data and archive rehydration before choosing a tier.</li><li><a href="https://learn.microsoft.com/en-us/azure/storage/common/storage-redundancy">Redundancy</a>: understand which failures replication protects against; replication is different from protection against an accidental delete.</li><li><a href="https://learn.microsoft.com/en-us/azure/storage/blobs/data-protection-overview">Data protection</a>: plan versioning, soft delete and recovery for the account's supported configuration.</li><li><a href="https://learn.microsoft.com/en-us/azure/storage/blobs/lifecycle-management-overview">Lifecycle policies</a>: manage aging data deliberately; review delete actions before enabling them.</li><li><a href="https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security">Network access</a> and <a href="https://learn.microsoft.com/en-us/rest/api/storageservices/cross-origin-resource-sharing--cors--support-for-the-azure-storage-services">CORS</a>: browser access can involve network and origin checks in addition to authorization.</li></ul>'''),
        section("progress", "Your learning progress", '''<p>Completion, lab milestones, latest quiz answers and your theme preference are stored only in this browser. If storage is blocked, the course keeps working for this visit and tells you it could not save. Export before clearing browser data or changing devices.</p><div class="actions only-js"><button class="btn" type="button" id="export-progress">Export progress</button><label class="btn" for="import-progress">Import progress</label><input type="file" id="import-progress" accept="application/json,.json"><button class="btn" type="button" id="reset-progress">Reset learning progress</button></div><p id="progress-status" role="status" aria-live="polite"></p><p>Reset clears lesson completion, lab milestones and quiz answers for this course. Other learning paths are unaffected.</p>''')
    ], minutes=10)
    return index, practice, glossary_page, quiz, reference
